import{_ as a,a as t,c as n,ac as o}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"第三册：培养技能 · Lesson 34 A happy discovery","description":"学习 分词状语的逻辑主语，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第三册：培养技能 · Lesson 34 A happy discovery","description":"学习 分词状语的逻辑主语，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第3册课时","summary":"学习 分词状语的逻辑主语，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第三册：培养技能 · Lesson 33 A day to remember","link":"/life/english/new-concept/book-3/unit-02/lesson-033"},"next":{"text":"第三册：培养技能 · Lesson 35 Justice was done","link":"/life/english/new-concept/book-3/unit-02/lesson-035"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第三册：培养技能 · Lesson 33 A day to remember","link":"/life/english/new-concept/book-3/unit-02/lesson-033"},"next":{"text":"第三册：培养技能 · Lesson 35 Justice was done","link":"/life/english/new-concept/book-3/unit-02/lesson-035"}},"headers":[],"relativePath":"life/english/new-concept/book-3/unit-02/lesson-034.md","filePath":"life/english/new-concept/book-3/unit-02/lesson-034.md"}'),i={name:"life/english/new-concept/book-3/unit-02/lesson-034.md"};function r(s,e,l,d,h,c){return t(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="第三册-培养技能-·-lesson-34-a-happy-discovery" tabindex="-1">第三册：培养技能 · Lesson 34 A happy discovery <a class="header-anchor" href="#第三册-培养技能-·-lesson-34-a-happy-discovery" aria-label="Permalink to &quot;第三册：培养技能 · Lesson 34 A happy discovery&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-3/contents">本册目录</a> · <a href="/life/english/new-concept/book-3/unit-02/overview">单元 2</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>从偶然发现旧物或价值线索学习推测与后续核实。发现令人兴奋并不意味着已经知道真相，描述时应给出判断依据。学习分词短语压缩背景信息，既保留时间和原因关系，也避免分词逻辑主语与主句主语不一致造成悬垂结构。</p><p>本课以主题阅读带动语言分析，学习重点如下。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>discovery</td><td>/dɪˈskʌvəri/</td><td>n.</td><td>发现</td><td>an unexpected discovery</td></tr><tr><td>antique</td><td>/ænˈtiːk/</td><td>n.</td><td>古董</td><td>a genuine antique</td></tr><tr><td>drawer</td><td>/drɔː/</td><td>n.</td><td>抽屉</td><td>an empty drawer</td></tr><tr><td>inspect</td><td>/ɪnˈspekt/</td><td>v.</td><td>仔细检查</td><td>inspect the frame</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>by chance — 偶然地</li><li>catch one&#39;s eye — 引起注意</li></ul><h2 id="语法讲解-分词状语的逻辑主语" tabindex="-1">语法讲解：分词状语的逻辑主语 <a class="header-anchor" href="#语法讲解-分词状语的逻辑主语" aria-label="Permalink to &quot;语法讲解：分词状语的逻辑主语&quot;">​</a></h2><p>现在分词短语可表示与主句同时的动作、原因或伴随情况，通常要求其逻辑主语与主句主语一致。Opening the drawer, I found ... 表示打开抽屉的是 I。若主句改为 a letter appeared，就可能让句面上变成信件打开抽屉。完成式 having done 强调分词动作先完成，但时间顺序已明确时不必机械使用。分词短语会压缩逻辑关系，若读者难以判断是原因还是时间，保留 when 或 because 从句往往更清楚。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>Looking beneath the frame, Maya noticed a small handwritten label.</p></blockquote><p>玛雅查看画框下方时，注意到一张小小的手写标签。</p><p>Looking 的逻辑主语为 Maya，与主句一致；分词短语交代发现时的动作背景。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>Looking under the table, a coin appeared 容易构成悬垂分词；应改为 I found a coin 或 When I looked ...。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>朗读分词短语后短停，再重读主句主语 I；用回听确认两个动作都归属于同一人。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>Sorting the books, I found a sketch between two pages. A date in the corner caught my eye. I photographed the sketch before asking the owner about its history.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>用三句描述发现旧物，包含一个主语一致的分词短语。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>分词主语清楚，发现后先记录再询问，未把猜测写成价值鉴定。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>例句是谁查看画框下方？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> Maya</p><p><strong>解析：</strong> 分词逻辑主语应与主句主语一致。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>修正：Opening the box, a note surprised me.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> When I opened the box, a note surprised me.</p><p><strong>解析：</strong> 明确从句主语，消除笔记打开盒子的错误关联。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>having checked 与 checking 相比更突出什么？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 动作已先完成。</p><p><strong>解析：</strong> 完成式分词强调先后关系。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：分词状语的逻辑主语。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-3/unit-02/grammar">单元语法</a> · <a href="/life/english/new-concept/book-3/unit-02/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-3/unit-02/review">单元自测</a></p><p><a href="/life/english/new-concept/book-3/unit-02/lesson-033">上一课</a> · <a href="/life/english/new-concept/book-3/unit-02/overview">单元目录</a> · <a href="/life/english/new-concept/book-3/unit-02/lesson-035">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const b=a(i,[["render",r]]);export{u as __pageData,b as default};
